<?php require 'config.php'; require_login(); $uid=$_SESSION['uid']; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf(); $action=$_POST['action']??''; if($action==='add'){ $name=trim($_POST['name']??''); if($name!=='' && mb_strlen($name)<=100){$stmt=$pdo->prepare('INSERT INTO subjects(user_id,name) VALUES(?,?)');$stmt->execute([$uid,$name]);redirect('subjects.php');} $error='Пән атауын енгізіңіз.'; } elseif($action==='delete'){ $stmt=$pdo->prepare('DELETE FROM subjects WHERE id=? AND user_id=?');$stmt->execute([(int)($_POST['id']??0),$uid]);redirect('subjects.php');} }
$stmt=$pdo->prepare('SELECT * FROM subjects WHERE user_id=? ORDER BY name');$stmt->execute([$uid]);$subjects=$stmt->fetchAll();require 'header.php'; ?><h1>Пәндер</h1><section class="panel"><form method="post" class="inline"><?=csrf()?><input type="hidden" name="action" value="add"><input name="name" placeholder="Мысалы: Программалау" maxlength="100" required><button>Қосу</button></form><?php if($error): ?><p class="error"><?=e($error)?></p><?php endif; ?></section><section class="panel"><?php foreach($subjects as $s): ?><div class="task"><strong><?=e($s['name'])?></strong><form method="post" onsubmit="return confirm('Пәнді өшіру керек пе?')"><?=csrf()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="danger">Өшіру</button></form></div><?php endforeach; ?><?php if(!$subjects): ?><p>Әзірше пән жоқ.</p><?php endif; ?></section><?php require 'footer.php'; ?>
